#[path="../../dm-analysis/examples/support/acquired_files.rs"]mod acquired_files;
#[path="../../dm-analysis/examples/support/reference_hierarchy.rs"]mod reference_hierarchy;
struct OracleWork{bytes:usize}impl dm_analysis::checker_effects::EffectReportWork for OracleWork{type Mark=usize;fn reserve(&mut self,n:usize)->io::Result<()>{self.bytes=self.bytes.checked_add(n).filter(|n|*n<=64*1024*1024).ok_or_else(||io::Error::new(io::ErrorKind::OutOfMemory,"standalone keyword oracle envelope"))?;Ok(())}fn mark(&mut self)->io::Result<usize>{Ok(self.bytes)}fn reconcile(&mut self,_:usize,_:usize)->io::Result<()>{Err(io::Error::other("standalone keyword oracle never credits live scratch"))}}
